spec.setup_code:
var sphereGeom = new api.THREE.SphereGeometry(1.2, 24, 16);
                var sphereMat = new api.THREE.MeshBasicMaterial({ color: 0x8A8272, wireframe: true });
                var sphereMesh = new api.THREE.Mesh(sphereGeom, sphereMat);
                api.group.add(sphereMesh);
                var axes = new api.THREE.AxesHelper(2);
                api.group.add(axes);
                var pointGeom = new api.THREE.SphereGeometry(0.12, 16, 16);
                var pointMat = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var point = new api.THREE.Mesh(pointGeom, pointMat);
                api.group.add(point);
                var r = 1.2;
                return {
                  update: function(t) {
                    var theta = t * 0.02;
                    var phi = Math.PI / 2 + Math.sin(t * 0.008) * (Math.PI / 3);
                    point.position.set(
                      r * Math.sin(phi) * Math.cos(theta),
                      r * Math.cos(phi),
                      r * Math.sin(phi) * Math.sin(theta)
                    );
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W/2, cy = H/2;
                    var R = Math.min(W, H) * 0.32;
                    ctx.strokeStyle = '#CFC7B8';
                    ctx.beginPath();
                    ctx.arc(cx, cy, R, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.beginPath();
                    ctx.ellipse(cx, cy, R, R * 0.35, 0, 0, Math.PI * 2);
                    ctx.stroke();
                    var theta = t * 0.03;
                    var phi = Math.PI / 2 + Math.sin(t * 0.008) * (Math.PI / 3);
                    var latRadius = R * Math.sin(phi);
                    var heightOffset = -R * Math.cos(phi) * 0.35;
                    var x = cx + latRadius * Math.cos(theta);
                    var y = cy + heightOffset - latRadius * Math.sin(theta) * 0.35;
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#333';
                    ctx.font = '13px sans-serif';
                    ctx.fillText('\u03B8 = ' + Math.round(theta * 180 / Math.PI % 360) + '\u00B0, \u03C6 = ' + Math.round(phi * 180 / Math.PI) + '\u00B0', 12, 20);
                  }
                };
